Source code in <code>src/jukto/payments.py</code> <pre><code>@dataclass(frozen=True)
class PaymentVerificationResult:
    reference: PaymentReference
    status: PaymentStatus
    validation_id: str | None = None
    bank_transaction_id: str | None = None
    requires_review: bool = True
    provider_status: str | None = None
    raw: dict[str, Any] = field(default_factory=dict, repr=False)

    @property
    def can_fulfill(self) -&gt; bool:
        return self.status == PaymentStatus.PAID and not self.requires_review

    @property
    def reconciliation_required(self) -&gt; bool:
        return self.status in (PaymentStatus.UNKNOWN, PaymentStatus.PENDING)
</code></pre>

Source code in <code>src/jukto/results.py</code> <pre><code>@dataclass(frozen=True)
class SMSSubmissionResult:
    provider: str
    status: Outcome
    request_id: Optional[str] = field(default=None, repr=False)
    recipients: tuple[SMSRecipientResult, ...] = ()
    provider_status: Any = field(default=None, repr=False)
    raw: Any = field(default=None, repr=False)

    @property
    def reconciliation_required(self) -&gt; bool:
        return self.status == Outcome.UNKNOWN or any(r.status == Outcome.UNKNOWN for r in self.recipients)
